(*
  Exact rank data is vendored from OpenAI tiktoken's public encoding assets:
    https://openaipublic.blob.core.windows.net/encodings/cl100k_base.tiktoken
      SHA-256 223921b76ee99bde995b7ff738513eef100fb51d18c93597a113bcffe865b2a7
    https://openaipublic.blob.core.windows.net/encodings/o200k_base.tiktoken
      SHA-256 446a9538cb6c348e3516120d7c08b09f57c36495e2acfffe59a5bf8b0cfb1a2d
  Encoding and pre-tokenization semantics follow:
    https://github.com/openai/tiktoken/blob/main/tiktoken_ext/openai_public.py
  Upstream license: MIT, Copyright (c) 2022 OpenAI, Shantanu Jain; exact text:
    https://github.com/openai/tiktoken/blob/main/LICENSE
  The rank payload below stores each mergeable token in rank order as a
  one-byte length followed by raw bytes, then base64-encodes that packed stream.
  *)

exception Error of string

type result = { encoding : string; token_count : int }

let max_input_bytes = 1_048_576

let cl100k_base_data = ""
let o200k_base_data = ""

type vocab = { ranks : (string, int) Hashtbl.t; max_token_bytes : int }

type encoding = Cl100k | O200k

let fail_internal () = raise (Error "embedded tokenizer vocabulary is invalid")

let base64_value = function
  | 'A'..'Z' as c -> Char.code c - Char.code 'A'
  | 'a'..'z' as c -> Char.code c - Char.code 'a' + 26
  | '0'..'9' as c -> Char.code c - Char.code '0' + 52
  | '+' -> 62
  | '/' -> 63
  | _ -> fail_internal ()

let decode_base64 text =
  let length = String.length text in
  if length mod 4 <> 0 then fail_internal ();
  let padding =
    if length = 0 then 0
    else if text.[length - 1] = '=' then
      if length > 1 && text.[length - 2] = '=' then 2 else 1
    else 0 in
  let output_length = length / 4 * 3 - padding in
  let output = Bytes.create output_length in
  let destination = ref 0 in
  let groups = length / 4 in
  for group = 0 to groups - 1 do
    let offset = group * 4 in
    let last = group = groups - 1 in
    let a = base64_value text.[offset]
    and b = base64_value text.[offset + 1] in
    let c, d =
      if text.[offset + 2] = '=' then (
        if not last || text.[offset + 3] <> '=' then fail_internal ();
        0, 0)
      else
        let c = base64_value text.[offset + 2] in
        let d = if text.[offset + 3] = '=' then (
          if not last then fail_internal ();
          0)
        else base64_value text.[offset + 3] in
        c, d in
    if (text.[offset + 2] = '=' || text.[offset + 3] = '=') && not last then
      fail_internal ();
    let first = (a lsl 2) lor (b lsr 4) in
    Bytes.set output !destination (Char.chr first);
    incr destination;
    if !destination < output_length then (
      let second = ((b land 15) lsl 4) lor (c lsr 2) in
      Bytes.set output !destination (Char.chr second);
      incr destination);
    if !destination < output_length then (
      let third = ((c land 3) lsl 6) lor d in
      Bytes.set output !destination (Char.chr third);
      incr destination)
  done;
  if !destination <> output_length then fail_internal ();
  Bytes.unsafe_to_string output

let load_vocab encoded expected_count =
  let packed = decode_base64 encoded in
  let packed_length = String.length packed in
  let ranks = Hashtbl.create expected_count in
  let offset = ref 0 and rank = ref 0 and max_token_bytes = ref 0 in
  while !offset < packed_length do
    let token_length = Char.code packed.[!offset] in
    incr offset;
    if token_length = 0 || token_length > packed_length - !offset ||
       !rank >= expected_count then fail_internal ();
    let token = String.sub packed !offset token_length in
    Hashtbl.add ranks token !rank;
    offset := !offset + token_length;
    max_token_bytes := max !max_token_bytes token_length;
    incr rank
  done;
  if !rank <> expected_count then fail_internal ();
  { ranks; max_token_bytes = !max_token_bytes }

let vocab_lock = Mutex.create ()
let vocab_cache : (encoding * vocab) list ref = ref []

let vocab_for encoding =
  Mutex.lock vocab_lock;
  Fun.protect ~finally:(fun () -> Mutex.unlock vocab_lock) (fun () ->
    match List.assoc_opt encoding !vocab_cache with
    | Some vocab -> vocab
    | None ->
        let encoded, expected_count = match encoding with
          | Cl100k -> cl100k_base_data, 100_256
          | O200k -> o200k_base_data, 199_998 in
        let vocab = load_vocab encoded expected_count in
        vocab_cache := (encoding, vocab) :: !vocab_cache;
        vocab)

type rune = {
  code : int; first_byte : int; after_byte : int;
  category : Uucp.Gc.t; white : bool
}

let utf8_error () = raise (Error "input is not valid UTF-8")

let decode_scalar text offset =
  let length = String.length text in
  let byte index = Char.code text.[index] in
  let continuation index =
    if index >= length then utf8_error ();
    let value = byte index in
    if value land 0xc0 <> 0x80 then utf8_error ();
    value land 0x3f in
  let first = byte offset in
  if first < 0x80 then first, offset + 1
  else if first >= 0xc2 && first <= 0xdf then
    (((first land 0x1f) lsl 6) lor continuation (offset + 1)), offset + 2
  else if first >= 0xe0 && first <= 0xef then (
    let second = continuation (offset + 1) in
    let third = continuation (offset + 2) in
    let code = ((first land 0x0f) lsl 12) lor (second lsl 6) lor third in
    if code < 0x800 || (code >= 0xd800 && code <= 0xdfff) then utf8_error ();
    code, offset + 3)
  else if first >= 0xf0 && first <= 0xf4 then (
    let second = continuation (offset + 1) in
    let third = continuation (offset + 2) in
    let fourth = continuation (offset + 3) in
    let code = ((first land 0x07) lsl 18) lor (second lsl 12) lor
      (third lsl 6) lor fourth in
    if code < 0x10000 || code > 0x10ffff then utf8_error ();
    code, offset + 4)
  else utf8_error ()

let decode_runes text =
  let byte_length = String.length text in
  let count = ref 0 and offset = ref 0 in
  while !offset < byte_length do
    let _, next = decode_scalar text !offset in
    offset := next;
    incr count
  done;
  let placeholder = {
    code = 0; first_byte = 0; after_byte = 0; category = `Cn; white = false
  } in
  let runes = Array.make !count placeholder in
  offset := 0;
  for index = 0 to !count - 1 do
    let code, next = decode_scalar text !offset in
    runes.(index) <- {
      code; first_byte = !offset; after_byte = next;
      category = Uucp.Gc.general_category (Uchar.unsafe_of_int code);
      white = Uucp.White.is_white_space (Uchar.unsafe_of_int code) };
    offset := next
  done;
  runes

let is_letter rune = match rune.category with
  | `Lu | `Ll | `Lt | `Lm | `Lo -> true
  | _ -> false

let is_number rune = match rune.category with
  | `Nd | `Nl | `No -> true
  | _ -> false

let is_upper rune = match rune.category with
  | `Lu | `Lt | `Lm | `Lo -> true
  | _ -> false

let is_o_lower rune = match rune.category with
  | `Ll | `Lm | `Lo | `Mn | `Mc | `Me -> true
  | _ -> false

let is_o_lower_without_marks rune = match rune.category with
  | `Ll | `Lm | `Lo -> true
  | _ -> false

let is_white rune = rune.white
let is_newline rune = rune.code = 0x0a || rune.code = 0x0d
let is_punctuation_class rune =
  not (is_white rune || is_letter rune || is_number rune)

let starts_case_insensitive text offset lower =
  let length = String.length lower in
  offset + length <= String.length text &&
  let rec equal index =
    index = length ||
    (Char.lowercase_ascii text.[offset + index] = lower.[index] && equal (index + 1)) in
  equal 0

let contraction_length text runes index =
  if index >= Array.length runes || runes.(index).code <> 0x27 then 0
  else
    let byte_offset = runes.(index).first_byte + 1 in
    if starts_case_insensitive text byte_offset "s" ||
       starts_case_insensitive text byte_offset "t" ||
       starts_case_insensitive text byte_offset "d" ||
       starts_case_insensitive text byte_offset "m" then 2
    else if starts_case_insensitive text byte_offset "ll" ||
            starts_case_insensitive text byte_offset "ve" ||
            starts_case_insensitive text byte_offset "re" then 3
    else 0

let run_while runes start predicate =
  let index = ref start in
  while !index < Array.length runes && predicate runes.(!index) do
    incr index
  done;
  !index

let optional_prefix runes index =
  index < Array.length runes && not (is_newline runes.(index)) &&
  not (is_letter runes.(index)) && not (is_number runes.(index))

let cl_word_end runes index =
  let start =
    if optional_prefix runes index && index + 1 < Array.length runes &&
       is_letter runes.(index + 1) then index + 1
    else index in
  if start < Array.length runes && is_letter runes.(start) then
    Some (run_while runes start is_letter)
  else None

let o_word_end runes index =
  let start =
    if optional_prefix runes index && index + 1 < Array.length runes then index + 1
    else index in
  if start >= Array.length runes then None
  else
    let upper_end = run_while runes start is_upper in
    let lower_end = run_while runes upper_end is_o_lower in
    if lower_end > upper_end then Some lower_end
    else
      let second_upper_end = run_while runes start is_upper in
      if second_upper_end = start then None
      else Some (run_while runes second_upper_end is_o_lower_without_marks)

let whitespace_end runes index = run_while runes index is_white

let last_newline_end runes start stop =
  let result = ref start in
  for index = start to stop - 1 do
    if is_newline runes.(index) then result := index + 1
  done;
  !result

let pretoken_end encoding text runes index =
  let length = Array.length runes in
  let contraction =
    if encoding = Cl100k then contraction_length text runes index else 0 in
  if encoding = Cl100k && contraction > 0 then index + contraction
  else
    let word_end = match encoding with
      | Cl100k -> cl_word_end runes index
      | O200k -> o_word_end runes index in
    match word_end with
    | Some word_end ->
        let suffix = contraction_length text runes word_end in
        word_end + suffix
    | None when is_number runes.(index) ->
        let stop = run_while runes index is_number in
        min stop (index + 3)
    | None ->
        let punctuation_start =
          if runes.(index).code = 0x20 && index + 1 < length &&
             is_punctuation_class runes.(index + 1) then index + 1
          else index in
        if is_punctuation_class runes.(punctuation_start) then (
          let stop = run_while runes punctuation_start is_punctuation_class in
          let rec suffix at =
            if at < length &&
               (is_newline runes.(at) ||
                (encoding = O200k && runes.(at).code = 0x2f))
            then suffix (at + 1) else at in
          suffix stop)
        else if is_white runes.(index) then (
          let stop = whitespace_end runes index in
          let newline_stop = last_newline_end runes index stop in
          if encoding = Cl100k && stop = length then stop
          else if newline_stop > index then newline_stop
          else if stop - index > 1 then stop - 1
          else stop)
        else index + 1

type node = {
  first : int;
  after : int;
  mutable previous : node option;
  mutable following : node option;
  mutable active : bool;
}

type edge = { left : node; right : node; rank : int }

type heap = { mutable entries : edge option array; mutable size : int }

let edge_before left right =
  left.rank < right.rank ||
  (left.rank = right.rank && left.left.first < right.left.first)

let heap_push heap edge =
  if heap.size = Array.length heap.entries then (
    let entries = Array.make (max 32 (heap.size * 2)) None in
    Array.blit heap.entries 0 entries 0 heap.size;
    heap.entries <- entries);
  let index = ref heap.size and moving = ref true in
  heap.size <- heap.size + 1;
  while !index > 0 && !moving do
    let parent = (!index - 1) / 2 in
    match heap.entries.(parent) with
    | Some parent_edge when edge_before edge parent_edge ->
        heap.entries.(!index) <- Some parent_edge;
        index := parent
    | _ -> moving := false
  done;
  heap.entries.(!index) <- Some edge

let heap_pop heap =
  if heap.size = 0 then None
  else
    let first = match heap.entries.(0) with Some edge -> edge | None -> assert false in
    heap.size <- heap.size - 1;
    let last_index = heap.size in
    let replacement = heap.entries.(last_index) in
    heap.entries.(last_index) <- None;
    if heap.size > 0 then (
      let replacement = match replacement with Some edge -> edge | None -> assert false in
      let index = ref 0 and moving = ref true in
      while !moving do
        let left_index = (!index * 2) + 1 in
        if left_index >= heap.size then moving := false
        else
          let right_index = left_index + 1 in
          let child_index =
            if right_index < heap.size then
              match heap.entries.(left_index), heap.entries.(right_index) with
              | Some left, Some right when edge_before right left -> right_index
              | _ -> left_index
            else left_index in
          match heap.entries.(child_index) with
          | Some child when edge_before child replacement ->
              heap.entries.(!index) <- Some child;
              index := child_index
          | _ -> moving := false
      done;
      heap.entries.(!index) <- Some replacement);
    Some first

let add_candidate heap vocab text left right =
  let bytes = right.after - left.first in
  if bytes <= vocab.max_token_bytes then
    match Hashtbl.find_opt vocab.ranks (String.sub text left.first bytes) with
    | None -> ()
    | Some rank -> heap_push heap { left; right; rank }

let adjacent left right =
  left.active && right.active &&
  match left.following with Some following -> following == right | None -> false

let make_nodes start stop =
  let count = stop - start in
  let nodes = Array.init count (fun offset -> {
    first = start + offset; after = start + offset + 1;
    previous = None; following = None; active = true }) in
  for index = 0 to count - 1 do
    if index > 0 then nodes.(index).previous <- Some nodes.(index - 1);
    if index + 1 < count then nodes.(index).following <- Some nodes.(index + 1)
  done;
  nodes.(0)

let bpe_count vocab text start stop =
  let byte_count = stop - start in
  if byte_count = 1 then 1
  else
    let first = make_nodes start stop in
    let heap = { entries = Array.make (min 256 (max 32 byte_count)) None; size = 0 } in
    let node = ref first in
    let building = ref true in
    while !building do
      match (!node).following with
      | None -> building := false
      | Some following ->
          add_candidate heap vocab text !node following;
          node := following
    done;
    let token_count = ref byte_count in
    let continue = ref true in
    while !continue do
      match heap_pop heap with
      | None -> continue := false
      | Some edge when adjacent edge.left edge.right ->
          let previous = edge.left.previous and following = edge.right.following in
          let merged = {
            first = edge.left.first; after = edge.right.after;
            previous; following; active = true } in
          edge.left.active <- false;
          edge.right.active <- false;
          edge.left.following <- None;
          edge.right.previous <- None;
          (match previous with Some node -> node.following <- Some merged | None -> ());
          (match following with Some node -> node.previous <- Some merged | None -> ());
          decr token_count;
          (match previous with Some node -> add_candidate heap vocab text node merged | None -> ());
          (match following with Some node -> add_candidate heap vocab text merged node | None -> ())
      | Some _ -> ()
    done;
    !token_count

let has_special_syntax text =
  let length = String.length text in
  let rec closing_marker index =
    index + 1 < length &&
    (text.[index] = '|' && text.[index + 1] = '>' || closing_marker (index + 1)) in
  let rec opening_marker index =
    index + 1 < length &&
    (text.[index] = '<' && text.[index + 1] = '|' &&
     closing_marker (index + 2) || opening_marker (index + 1)) in
  opening_marker 0

(* Counts plain UTF-8 text only. Message framing and special-token IDs are not
   included; any special-token spelling is rejected rather than guessed. *)
let count_tokens ~encoding text =
  let selected = match encoding with
    | "cl100k_base" -> Cl100k
    | "o200k_base" -> O200k
    | _ -> raise (Error "unknown tokenizer encoding") in
  if String.length text > max_input_bytes then
    raise (Error "tokenizer input exceeds the 1 MiB byte limit");
  if has_special_syntax text then
    raise (Error "special-token text is unsupported by the plain-text counter");
  if text = "" then { encoding; token_count = 0 }
  else
    let runes = decode_runes text in
    let vocab = vocab_for selected in
    let total = ref 0 and index = ref 0 in
    while !index < Array.length runes do
      let stop = pretoken_end selected text runes !index in
      if stop <= !index then fail_internal ();
      let byte_start = runes.(!index).first_byte in
      let byte_stop = runes.(stop - 1).after_byte in
      total := !total + bpe_count vocab text byte_start byte_stop;
      index := stop
    done;
    { encoding; token_count = !total }
